templates.template:
// 삽입 위치: 빈 파일 전체
// 용도: OJ 프로그램의 Main 클래스와 시작 틀 만들기
// 문제 표현: 프로그램을 작성하라 / Main 클래스를 작성하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
public class ${primary_type_name} {
	public static void main(String[] args) {
		${cursor}
	}
}

// 삽입 위치: 클래스 안·메소드 밖
// 용도: 프로그램 실행 시작 메소드 만들기
// 문제 표현: 다음 main()을 실행하라 / 실행 결과를 출력하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
public static void main(String[] args) {
	${cursor}
}

// 삽입 위치: main() 등 메소드 안
// 용도: 값을 출력한 뒤 줄바꿈하기
// 문제 표현: 한 줄에 출력하라 / 각 결과를 줄마다 출력하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
System.out.println(${value:link('0')});${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 줄바꿈 없이 이어서 출력하기
// 문제 표현: 같은 줄에 출력하라 / 공백으로 구분하여 출력하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
System.out.print(${value:link('0')});${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 소수점 자릿수와 출력 형식 맞추기
// 문제 표현: 소수점 아래 첫째 자리까지 / 형식에 맞춰 출력하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
System.out.printf("%.1f%n", ${value:link('0.0')});${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 키보드·표준 입력을 받을 Scanner 만들기
// 문제 표현: 입력받아라 / 정수 또는 문자열이 주어진다 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
${imports:import(java.util.Scanner)}Scanner ${scanner} = new Scanner(System.in);
${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: Scanner로 정수 한 개 읽기
// 문제 표현: 정수 N을 입력받아라 / 나이·개수를 입력받아라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
int ${number} = ${scanner}.nextInt();${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: Scanner로 실수 한 개 읽기
// 문제 표현: 실수를 입력받아라 / 체중·반지름을 실수로 입력받아라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
double ${number} = ${scanner}.nextDouble();${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 공백으로 구분된 문자열 한 개 읽기
// 문제 표현: 이름·단어를 입력받아라 / 공백 없는 문자열이 주어진다 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
String ${text} = ${scanner}.next();${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 공백을 포함한 한 줄 전체 읽기
// 문제 표현: 문장 한 줄을 입력받아라 / 공백을 포함한 문자열 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
String ${text} = ${scanner}.nextLine();${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 조건을 만족할 때만 작업하기
// 문제 표현: 만약 ~이면 / ~인 경우에만 실행하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
if (${condition:link('true')}) {
	${cursor}
}

// 삽입 위치: main() 등 메소드 안
// 용도: 조건에 따라 두 작업 중 하나 실행하기
// 문제 표현: ~이면 합격, 아니면 불합격 / 조건에 따라 나누어라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
if (${condition:link('true')}) {
	${cursor}
} else {

}

// 삽입 위치: main() 등 메소드 안
// 용도: 정해진 값별로 작업 분기하기
// 문제 표현: 메뉴 번호·등급·연산 기호에 따라 / switch문을 사용하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
switch (${key:link('0')}) {
case ${caseValue:link('0')}:
	${cursor}
	break;
default:
	break;
}

// 삽입 위치: main() 등 메소드 안
// 용도: 정해진 횟수만큼 반복하기
// 문제 표현: N번 반복하라 / N개의 값을 입력받아라 / 0부터 N-1까지 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
for (int ${i} = 0; ${i} < ${count:link('5')}; ${i}++) {
	${cursor}
}

// 삽입 위치: main() 등 메소드 안
// 용도: 종료 조건을 만날 때까지 반복하기
// 문제 표현: -1이 입력될 때까지 / exit을 입력하면 종료 / 반복 입력받아라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
while (${condition:link('true')}) {
	${cursor}
}

// 삽입 위치: main() 등 메소드 안
// 용도: 작업을 최소 한 번 실행한 뒤 반복 판단하기
// 문제 표현: 적어도 한 번 실행하라 / do-while문을 사용하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
do {
	${cursor}
} while (${condition:link('false')});

// 삽입 위치: main() 등 메소드 안
// 용도: 조건을 만나 반복문을 끝내기
// 문제 표현: -1을 입력하면 종료 / 찾으면 반복을 중단하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
if (${condition:link('true')}) {
	break;
}${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 현재 회차를 건너뛰고 다음 반복으로 가기
// 문제 표현: 음수는 제외하라 / 조건에 맞지 않으면 건너뛰어라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
if (${condition:link('true')}) {
	continue;
}${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 고정 개수의 값을 저장할 배열 만들기
// 문제 표현: 정수 N개를 배열에 저장하라 / 크기가 N인 배열 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
${elementType:link('int')}[] ${array} = new ${elementType}[${size:link('5')}];${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 배열의 인덱스로 모든 원소 처리하기
// 문제 표현: 배열의 모든 원소를 순서대로 / 각 원소를 변경하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
for (int ${i} = 0; ${i} < ${array}.length; ${i}++) {
	${cursor}
}

// 삽입 위치: main() 등 메소드 안
// 용도: 배열의 값을 하나씩 꺼내 순회하기
// 문제 표현: 배열의 모든 값을 출력하라 / for-each문을 사용하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
for (${elementType:link('int')} ${value} : ${array}) {
	${cursor}
}

// 삽입 위치: main() 등 메소드 안
// 용도: 행·열로 된 2차원 배열 만들고 순회하기
// 문제 표현: 행렬 / N행 M열 / 2차원 배열의 모든 원소 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
${elementType:link('int')}[][] ${matrix} = new ${elementType}[${rows:link('3')}][${cols:link('4')}];
for (int ${i} = 0; ${i} < ${matrix}.length; ${i}++) {
	for (int ${j} = 0; ${j} < ${matrix}[${i}].length; ${j}++) {
		${cursor}
	}
}

// 삽입 위치: main() 등 메소드 안
// 용도: 예외 발생 시 처리하고 정리 작업하기
// 문제 표현: 예외를 처리하라 / 잘못된 입력에도 종료되지 않게 / try-catch → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
try {
	${cursor}
} catch (${exceptionType:link('NumberFormatException')} ${e}) {
	// 예외 발생 시 처리
} finally {
	// 항상 실행할 처리
}

// 삽입 위치: 클래스 선언 위치
// 용도: 필드·생성자·getter·setter가 있는 보조 클래스 만들기
// 문제 표현: ~클래스를 작성하라 / 멤버 변수를 private으로 선언하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
class ${ClassName} {
	private ${fieldType:link('int')} ${value};

	public ${ClassName}(${fieldType} ${value}) {
		this.${value} = ${value};
	}

	public ${fieldType} getValue() {
		return ${value};
	}

	public void setValue(${fieldType} ${value}) {
		this.${value} = ${value};
	}
	${cursor}
}

// 삽입 위치: 클래스 안·메소드 밖
// 용도: 객체를 생성할 때 전달값으로 필드 초기화하기
// 문제 표현: 생성자를 작성하라 / 생성자로 멤버 변수를 초기화하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
public ${enclosing_type}(${fieldType:link('int')} ${value}) {
	this.${value} = ${value};
	${cursor}
}

// 삽입 위치: 클래스 안·메소드 밖
// 용도: 같은 클래스의 다른 생성자 호출하기
// 문제 표현: this()를 이용하라 / 기본 생성자에서 다른 생성자를 호출하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
public ${enclosing_type}() {
	this(${argument:link('0')});
	${cursor}
}

// 삽입 위치: 클래스 안·메소드 밖
// 용도: 입력값을 받아 결과를 반환하는 메소드 만들기
// 문제 표현: ~메소드를 작성하라 / 계산한 값을 리턴하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
public ${returnType:link('int')} ${methodName}(${parameterType:link('int')} ${value}) {
	${cursor}
	return ${value};
}

// 삽입 위치: 클래스 안·메소드 밖
// 용도: 객체 생성 없이 호출할 static 메소드 만들기
// 문제 표현: static 메소드 / 클래스 이름으로 호출 / 전역 함수처럼 사용 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
public static ${returnType:link('int')} ${methodName}(${parameterType:link('int')} ${value}) {
	${cursor}
	return ${value};
}

// 삽입 위치: main() 등 메소드 안
// 용도: 생성자를 호출해 객체 한 개 만들기
// 문제 표현: 객체를 생성하라 / 인스턴스를 생성하라 / new로 생성하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
${ClassName} ${object} = new ${ClassName}(${arguments});${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 객체 배열을 만들고 각 원소의 객체 생성하기
// 문제 표현: 객체 N개를 배열에 저장하라 / 객체 배열을 생성하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
${ClassName}[] ${objects} = new ${ClassName}[${size:link('5')}];
for (int ${i} = 0; ${i} < ${objects}.length; ${i}++) {
	${objects}[${i}] = new ${ClassName}(${arguments});
	${cursor}
}

// 삽입 위치: 클래스 선언 위치
// 용도: 부모 클래스를 상속하고 부모 생성자 호출하기
// 문제 표현: ~를 상속받는 클래스를 작성하라 / super()를 이용하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
class ${Child} extends ${Parent} {
	public ${Child}(${parameterType:link('int')} ${value}) {
		super(${value});
		${cursor}
	}
}

// 삽입 위치: 클래스 안·메소드 밖
// 용도: 부모의 void 메소드를 자식에서 재정의하기
// 문제 표현: 메소드를 오버라이딩하라 / 상속받은 동작을 재정의하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
@Override
public void ${methodName}() {
	${cursor}
}

// 삽입 위치: main() 등 메소드 안
// 용도: 실제 객체 타입을 확인한 후 다운캐스팅하기
// 문제 표현: instanceof로 구분하라 / 자식 타입으로 변환하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
if (${object} instanceof ${Child}) {
	${Child} ${child} = (${Child}) ${object};
	${cursor}
}

// 삽입 위치: 클래스 선언 위치
// 용도: 구현을 자식에게 맡기는 추상 클래스 선언하기
// 문제 표현: 추상 클래스 / abstract 메소드를 선언하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
abstract class ${Base} {
	public abstract void ${methodName}();
	${cursor}
}

// 삽입 위치: 클래스 선언 위치
// 용도: 클래스가 구현할 메소드 규격 선언하기
// 문제 표현: 인터페이스를 작성하라 / interface를 선언하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
interface ${InterfaceName} {
	void ${methodName}();
	${cursor}
}

// 삽입 위치: 클래스 선언 위치
// 용도: 인터페이스를 구현하는 클래스 만들기
// 문제 표현: ~인터페이스를 구현하라 / implements를 사용하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
class ${ClassName} implements ${InterfaceName} {
	@Override
	public void ${methodName}() {
		${cursor}
	}
}

// 삽입 위치: 클래스 안·메소드 밖
// 용도: 객체를 설명하는 문자열 반환하기
// 문제 표현: toString()을 재정의하라 / 객체 출력 시 지정한 문자열 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
@Override
public String toString() {
	return ${expression:link('""')};
}${cursor}

// 삽입 위치: main() 등 메소드 안
// 용도: 숫자 문자열을 int 정수로 바꾸기
// 문제 표현: 문자열을 정수로 변환하라 / Integer.parseInt를 사용하라 → 이 틀을 사용하고 변수·조건·타입을 문제에 맞게 수정하세요.
