// 삽입 위치: Main.java 전체 교체 (기존 내용을 백업한 뒤 파일을 비우고 사용)
// 용도: 두 사람의 가중 감점 계산과 비교
// 문제 표현: 지각·결석 감점 / 점수가 높은 사람 / 같으면 equal
// 수정할 곳: 기준 점수와 감점 상수, 동점 처리, 출력 문구
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int BASE = 100, LATE = 3, ABSENT = 8;
        String[] name = new String[2];
        int[] deducted = new int[2];
        int[] score = new int[2];
        for (int i = 0; i < 2; i++) {
            name[i] = sc.next();
            int late = sc.nextInt(), absent = sc.nextInt();
            deducted[i] = late * LATE + absent * ABSENT;
            score[i] = BASE - deducted[i];
            System.out.println(deducted[i] + " points will be deducted from the attendance points of " + name[i] + ".");
        }
        if (score[0] == score[1]) System.out.println("equal");
        else {
            int win = score[0] > score[1] ? 0 : 1;
            System.out.println(name[win] + " attendance points are greater than " + name[1 - win] + ".");
            System.out.println(name[win] + " attendance points are " + score[win] + ".");
        }
        sc.close();
    }
}
