// 용도: 2진 문자열의 개별 상태 비트 판별
// 문제 표현: 00001101처럼 입력 / 비트 0·1·2·3의 상태
// 수정할 곳: 각 비트 번호, 상태별 출력 문구
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int status = Integer.parseInt(sc.next(), 2); // 2진 문자열, 선행 0 허용
        System.out.println("power: " + ((status & (1 << 0)) != 0 ? "on" : "off"));
        System.out.println("door: " + ((status & (1 << 1)) != 0 ? "closed" : "open"));
        System.out.println("light: " + ((status & (1 << 2)) != 0 ? "on" : "off"));
        System.out.println("temperature: " + ((status & (1 << 3)) != 0 ? "less than 3" : "greater than or equal to 3"));
        sc.close();
    }
}
