// 삽입 위치: Main.java 전체 교체 (기존 내용을 백업한 뒤 파일을 비우고 사용)
// 용도: 십진 정수에서 상태 비트·하위 비트 값 추출
// 문제 표현: 비트 6·7은 상태 / 하위 비트는 온도
// 수정할 곳: 필드 폭 WIDTH와 비트 번호; 원문의 0~5비트와 0~31 표기 충돌 시 시험 조건 확인
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int status = sc.nextInt();
        final int WIDTH = 6; // 비트 0~5는 6비트: 값 범위 0~63. 5비트를 요구하면 5로 수정.
        int temperature = status & ((1 << WIDTH) - 1);
        boolean air = (status & (1 << 6)) != 0;
        boolean running = (status & (1 << 7)) != 0;
        System.out.println("running: " + (running ? "on" : "off"));
        System.out.println("air conditioner: " + (air ? "on" : "off"));
        System.out.println("temperature: " + temperature);
        sc.close();
    }
}
