// 용도: 대응 배열에서 이름으로 값 반복 검색
// 문제 표현: 과목명으로 학점 / 없으면 none / stop이면 종료
// 수정할 곳: key·value 배열, 종료어, 미발견 출력
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] key = {"C", "C++", "Python", "Java", "HTML5"};
        String[] value = {"A", "B+", "B", "A+", "D"};
        while (sc.hasNext()) {
            String query = sc.next();
            if (query.equals("stop")) break;
            int found = -1;
            for (int i = 0; i < key.length; i++) {
                if (key[i].equals(query)) { found = i; break; }
            }
            System.out.println(found < 0 ? "none" : value[found]);
        }
        sc.close();
    }
}
