// 삽입 위치: Main.java 전체 교체 (기존 내용을 백업한 뒤 파일을 비우고 사용)
// 용도: 잘못된 입력 제외하며 양수의 합·개수·평균 누적
// 문제 표현: -1까지 / 문자열·실수 제외 / InputMismatchException
// 수정할 곳: 종료값, 허용 범위, 제외 메시지, 평균 출력 여부
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
import java.util.InputMismatchException;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long sum = 0;
        int count = 0;
        while (sc.hasNext()) {
            try {
                int n = sc.nextInt();
                if (n == -1) break;
                if (n <= 0) { System.out.println(n + " is excluded."); continue; }
                sum += n;
                count++;
            } catch (InputMismatchException e) {
                String invalid = sc.next(); // 잘못된 토큰을 소비해야 무한 반복하지 않음
                System.out.println(invalid + " is excluded.");
            }
        }
        System.out.println("The sum is " + sum + " and the number is " + count + ".");
        // 평균까지 요구하면 다음 줄을 활성화하고 출력 형식을 수정.
        // if (count > 0) System.out.printf(java.util.Locale.US, "%.2f%n", (double) sum / count);
        sc.close();
    }
}
