// 용도: 메뉴 검색·수량 검증·가격 계산 반복
// 문제 표현: 없는 메뉴 / 수량은 양의 정수 / Quit까지 주문
// 수정할 곳: 메뉴·단가 배열, 종료어, 오류 시 남은 줄 소비 정책
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
import java.util.InputMismatchException;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] menu = {"Americano", "Cappuccino", "Latte", "Espresso"};
        int[] price = {3000, 3500, 4000, 5000};
        while (sc.hasNext()) {
            String name = sc.next();
            if (name.equals("Quit")) break;
            int index = -1;
            for (int i = 0; i < menu.length; i++) if (menu[i].equals(name)) { index = i; break; }
            if (index < 0) {
                System.out.println(name + " is not available.");
                if (sc.hasNextLine()) sc.nextLine(); // 이 템플릿은 주문 한 건이 한 줄
                continue;
            }
            try {
                int cups = sc.nextInt();
                if (cups <= 0) System.out.println("Please enter a positive integer for the number of cups.");
                else System.out.println("The price is " + (long) cups * price[index] + " won.");
            } catch (InputMismatchException e) {
                System.out.println("Please enter a positive integer for the number of cups.");
            }
            if (sc.hasNextLine()) sc.nextLine();
        }
        sc.close();
    }
}
