// 용도: 객체의 치수 초기화·증가·계산·상태 판단
// 문제 표현: 직육면체 / increase / 부피가 0인지
// 수정할 곳: 필드와 계산식, 메소드명 volume/getVolume, 문장 끝 마침표
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
class Cuboid {
    private int width, height, depth;
    public Cuboid(int width, int height, int depth) {
        this.width = width; this.height = height; this.depth = depth;
    }
    public long volume() { return (long) width * height * depth; }
    public long getVolume() { return volume(); } // 주어진 main의 메소드명에 맞춰 사용
    public void increase(int w, int h, int d) { width += w; height += h; depth += d; }
    public boolean isZero() { return volume() == 0; }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Cuboid c = new Cuboid(sc.nextInt(), sc.nextInt(), sc.nextInt());
        System.out.println("The volume of the cuboid is " + c.volume() + ".");
        c.increase(sc.nextInt(), sc.nextInt(), sc.nextInt());
        System.out.println("The volume of the cuboid is " + c.volume() + ".");
        System.out.println("The volume of the cuboid is " + (c.isZero() ? "zero" : "not zero") + ".");
        sc.close();
    }
}
