// 삽입 위치: Main.java 전체 교체 (기존 내용을 백업한 뒤 파일을 비우고 사용)
// 용도: 용량 제한 객체에 양수 저장·출력·평균
// 문제 표현: 최대 10개 / 초과는 버린다 / -1 종료 / 평균 한 자리
// 수정할 곳: LIMIT, 입력 허용 조건, 빈 배열 평균 처리, 소수점 자리
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
import java.util.Locale;
class Average {
    private static final int LIMIT = 10;
    private int[] values = new int[LIMIT];
    private int nextIndex = 0;
    public void put(int n) {
        if (n > 0 && nextIndex < values.length) values[nextIndex++] = n;
    }
    public void showAll() {
        for (int i = 0; i < nextIndex; i++) {
            if (i > 0) System.out.print(" ");
            System.out.print(values[i]);
        }
        System.out.println();
    }
    public double getAvg() {
        long sum = 0;
        for (int i = 0; i < nextIndex; i++) sum += values[i];
        return nextIndex == 0 ? 0.0 : (double) sum / nextIndex;
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Average avg = new Average();
        while (sc.hasNextInt()) { int n = sc.nextInt(); if (n == -1) break; avg.put(n); }
        avg.showAll();
        System.out.printf(Locale.US, "The average is %.1f.%n", avg.getAvg());
        sc.close();
    }
}
