// 용도: static 메소드로 두 배열 연결·출력
// 문제 표현: ArrayUtil / concat / 새 배열을 리턴하라
// 수정할 곳: 배열 크기 N·M, 원소 타입, 괄호·공백 출력
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
class ArrayUtil {
    public static int[] concat(int[] a, int[] b) {
        int[] result = new int[a.length + b.length];
        for (int i = 0; i < a.length; i++) result[i] = a[i];
        for (int i = 0; i < b.length; i++) result[a.length + i] = b[i];
        return result;
    }
    public static void print(int[] a) {
        System.out.print("[ ");
        for (int n : a) System.out.print(n + " ");
        System.out.println("]");
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 4, M = 4; // 길이가 입력으로 주어지면 sc.nextInt()로 변경
        int[] a = new int[N], b = new int[M];
        for (int i = 0; i < a.length; i++) a[i] = sc.nextInt();
        for (int i = 0; i < b.length; i++) b[i] = sc.nextInt();
        ArrayUtil.print(ArrayUtil.concat(a, b));
        sc.close();
    }
}
