// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
class Dictionary {
    private static String[] kor = {"sarang", "agi", "don", "mirae", "heemang"};
    private static String[] eng = {"love", "baby", "money", "future", "hope"};
    public static String kor2Eng(String word) {
        for (int i = 0; i < kor.length; i++) if (kor[i].equals(word)) return eng[i];
        return null;
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            String word = sc.next();
            if (word.equals("exit")) { System.out.println("The program has ended."); break; }
            String found = Dictionary.kor2Eng(word);
            if (found == null) System.out.println(word + " is not in my dictionary.");
            else System.out.println(word + " is " + found + " in English.");
        }
        sc.close();
    }
}
