// 용도: 부모의 저장 메소드를 재정의해 값 변환
// 문제 표현: BaseArray 상속 / 임계값보다 크면 1 아니면 0
// 수정할 곳: SIZE·THRESHOLD, > 또는 >= 조건, 변환값
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
class BaseArray {
    protected int[] array;
    protected int nextIndex = 0;
    public BaseArray(int size) { array = new int[size]; }
    public int length() { return array.length; }
    public void add(int n) { if (nextIndex < array.length) array[nextIndex++] = n; }
    public void print() {
        for (int i = 0; i < nextIndex; i++) {
            if (i > 0) System.out.print(" ");
            System.out.print(array[i]);
        }
        System.out.println();
    }
}
class BinaryArray extends BaseArray {
    private int threshold;
    public BinaryArray(int size, int threshold) { super(size); this.threshold = threshold; }
    @Override public void add(int n) { super.add(n > threshold ? 1 : 0); }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int SIZE = 10, THRESHOLD = 50;
        BinaryArray a = new BinaryArray(SIZE, THRESHOLD);
        for (int i = 0; i < a.length(); i++) a.add(sc.nextInt());
        a.print();
        sc.close();
    }
}
