// 용도: 인터페이스·default 메소드·객체 배열 다형성
// 문제 표현: Shape 인터페이스 구현 / redraw / 면적 계산
// 수정할 곳: 도형 종류, PI, 입력 개수, draw와 getArea 구현
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;

interface Shape {
    double PI = 3.14;
    void draw();
    double getArea();
    default void redraw() { System.out.print("redraw "); draw(); }
}

class Circle implements Shape {
    private int radius;
    public Circle(int radius) { this.radius = radius; }
    @Override public void draw() { System.out.println("circle with radius " + radius); }
    @Override public double getArea() { return PI * radius * radius; }
}
class Rect implements Shape {
    private int width, height;
    public Rect(int width, int height) { this.width = width; this.height = height; }
    @Override public void draw() { System.out.println(width + "x" + height + " rectangular"); }
    @Override public double getArea() { return (double) width * height; }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Shape[] shapes = {new Circle(sc.nextInt()), new Rect(sc.nextInt(), sc.nextInt()), new Rect(sc.nextInt(), sc.nextInt())};
        for (Shape s : shapes) s.redraw(); // 실제 객체의 draw가 호출됨
        for (Shape s : shapes) System.out.printf(java.util.Locale.US, "The area is %.1f.%n", s.getArea());
        sc.close();
    }
}
