// 삽입 위치: Main.java 전체 교체 (기존 내용을 백업한 뒤 파일을 비우고 사용)
// 용도: 추상 클래스와 연산별 자식 객체 선택
// 문제 표현: Add Sub Mul Div / calculate / 0 나누기 오류면 종료
// 수정할 곳: 연산 종류, 정수·실수 여부, 오류 정책과 출력
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
abstract class Calc {
    public String errorMsg;
    protected int a, b;
    public void setValue(int a, int b) { this.a = a; this.b = b; errorMsg = null; }
    public abstract int calculate();
}
class Add extends Calc { @Override public int calculate() { return a + b; } }
class Sub extends Calc { @Override public int calculate() { return a - b; } }
class Mul extends Calc { @Override public int calculate() { return a * b; } }
class Div extends Calc {
    @Override public int calculate() {
        if (b == 0) { errorMsg = "You cannot divide by zero."; return 0; }
        return a / b;
    }
}
class Calculator {
    public void run() {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int a = sc.nextInt(), b = sc.nextInt();
            String op = sc.next();
            Calc obj;
            switch (op) {
                case "+": obj = new Add(); break;
                case "-": obj = new Sub(); break;
                case "*": obj = new Mul(); break;
                case "/": obj = new Div(); break;
                default: System.out.println("Wrong operator"); sc.close(); return;
            }
            obj.setValue(a, b);
            int result = obj.calculate();
            if (obj.errorMsg != null) { System.out.println(obj.errorMsg + " Exit"); break; }
            System.out.println("Result is " + result + ".");
        }
        sc.close();
    }
}
public class Main {
    public static void main(String[] args) { new Calculator().run(); }
}
