// 삽입 위치: Main.java 전체 교체 (기존 내용을 백업한 뒤 파일을 비우고 사용)
// 용도: toString·equals로 객체 정보 출력·동등성 판단
// 문제 표현: 이름도 같고 학번도 같으면 / 동일 학생인지 비교
// 수정할 곳: 필드, 동등성 조건, toString 출력; equals와 hashCode를 함께 수정
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
import java.util.Objects;
class Student {
    private String name;
    private int id;
    public Student(String name, int id) { this.name = name; this.id = id; }
    @Override public String toString() { return name + "'s id is " + id + "."; }
    @Override public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Student other = (Student) obj;
        return id == other.id && Objects.equals(name, other.name);
    }
    @Override public int hashCode() { return Objects.hash(name, id); }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Student a = new Student(sc.next(), sc.nextInt());
        Student b = new Student(sc.next(), sc.nextInt());
        System.out.println(a);
        System.out.println(a.equals(b) ? "They are the same." : "They are different.");
        sc.close();
    }
}
