// 삽입 위치: Main.java 전체 교체 (기존 내용을 백업한 뒤 파일을 비우고 사용)
// 용도: 한 줄 분리·대소문자 정규화·등급 평균
// 문제 표현: A B C 학점 / 소문자 허용 / 오류 문자 / Quit 종료
// 수정할 곳: 학점별 점수표, 오류 시 평균 생략 정책, 소수점 자리
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
import java.util.Locale;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.equals("Quit")) break;
            if (line.isEmpty()) continue;
            String[] grades = line.toUpperCase(Locale.ROOT).split("\\s+");
            boolean error = false;
            double sum = 0;
            for (String grade : grades) {
                switch (grade) {
                    case "A": sum += 100; break;
                    case "B": sum += 90; break;
                    case "C": sum += 80; break;
                    case "D": sum += 70; break;
                    case "F": break;
                    default: System.out.println("Input error:" + grade); error = true;
                }
            }
            if (!error) System.out.printf(Locale.US, "Average is %.2f.%n", sum / grades.length);
        }
        sc.close();
    }
}
