// 삽입 위치: Main.java 전체 교체 (기존 내용을 백업한 뒤 파일을 비우고 사용)
// 용도: 문자 배열 대칭 교환과 단어 맞히기
// 문제 표현: toCharArray / abcd를 dcba로 / Quit 종료
// 수정할 곳: 단어 배열, 종료어, 성공·실패 문구와 >> 프롬프트
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
class WordShuffleGame {
    private String[] words = {"vibrate", "extract", "nation", "connect", "lovely"};
    private String shuffle(String src) {
        char[] chars = src.toCharArray();
        for (int left = 0, right = chars.length - 1; left < right; left++, right--) {
            char tmp = chars[left]; chars[left] = chars[right]; chars[right] = tmp;
        }
        return new String(chars);
    }
    public void run() {
        Scanner sc = new Scanner(System.in);
        for (String answer : words) {
            System.out.println(shuffle(answer));
            System.out.print(">>"); // 이 자료의 출력 예시에 명시된 프롬프트. 다른 OJ에서 불필요하면 삭제.
            if (!sc.hasNext()) break;
            String user = sc.next();
            if (user.equals("Quit")) break;
            if (user.equals(answer)) System.out.println("Success!!!");
            else System.out.println("Fail!!! It is " + answer + ".");
        }
        sc.close();
    }
}
public class Main {
    public static void main(String[] args) { new WordShuffleGame().run(); }
}
