// 삽입 위치: Main.java 전체 교체 (기존 내용을 백업한 뒤 파일을 비우고 사용)
// 용도: Vector에 양수 저장 후 최솟값 검색
// 문제 표현: -1까지 Vector<Integer> / 가장 작은 수
// 수정할 곳: 입력 조건, 종료값, 최솟값·최댓값 비교식, 빈 입력 처리
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
import java.util.Vector;
class IntegerVector {
    private Vector<Integer> values = new Vector<>();
    private void read() {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == -1) break;
            if (n > 0) values.add(n);
        }
        sc.close();
    }
    private int findLeastNumber() {
        int least = values.get(0);
        for (int n : values) if (n < least) least = n;
        return least;
    }
    public void run() {
        read();
        if (values.isEmpty()) return; // 원문에 없는 빈 입력 정책은 유사 문제 조건에 맞게 변경
        System.out.println("The least integer is " + findLeastNumber() + ".");
    }
}
public class Main {
    public static void main(String[] args) { new IntegerVector().run(); }
}
