// 삽입 위치: Main.java 전체 교체 (기존 내용을 백업한 뒤 파일을 비우고 사용)
// 용도: HashMap에 입력 저장 후 별도 검색 단계
// 문제 표현: 이름·가격을 저장 / quit 후 이름으로 검색
// 수정할 곳: 키·값 타입, 종료어, 자료에 있는 프롬프트 유지 여부
// OJ: Main.java, public class Main 한 개, package 없음. 출력 문자열은 문제의 예시와 일치시킬 것.
import java.util.Scanner;
import java.util.HashMap;
class StockHashMap {
    private HashMap<String, Integer> stockMap = new HashMap<>();
    private Scanner sc = new Scanner(System.in);
    private void read() {
        // 이 자료는 프롬프트도 출력 예시에 포함. 다른 OJ에서 요구하지 않으면 아래 두 출력문 삭제.
        System.out.println("input name and price (samsung 75000)");
        while (sc.hasNext()) {
            System.out.print("name price>>");
            String name = sc.next();
            if (name.equals("quit")) break;
            stockMap.put(name, sc.nextInt()); // 같은 이름이면 새 가격으로 덮어씀
        }
    }
    private void search() {
        System.out.println("search"); // 출력 예시의 프롬프트
        while (sc.hasNext()) {
            System.out.print("name>>");
            String name = sc.next();
            if (name.equals("quit")) break;
            Integer price = stockMap.get(name); // 미발견을 위해 int 대신 Integer
            if (price == null) System.out.println(name + "is not available."); // 원문 문자열: 이름 뒤 공백 없음
            else System.out.println(name + " " + price + " won");
        }
    }
    public void run() { read(); search(); sc.close(); }
}
public class Main {
    public static void main(String[] args) { new StockHashMap().run(); }
}
